import{_ as s,l as o,o as e,c as l,v as t,p as n,x as r,d as h,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"胶去除与灰化","description":"","frontmatter":{"title":"胶去除与灰化","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/resist-strip-ash.md","filePath":"litho/resist-strip-ash.md","lastUpdated":1789023840000}'),E={name:"litho/resist-strip-ash.md"};function _(c,a,A,B,m,u){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="胶去除与灰化" tabindex="-1">胶去除与灰化 <a class="header-anchor" href="#胶去除与灰化" aria-label="Permalink to &quot;胶去除与灰化&quot;">​</a></h1><div class="epigraph"><p>转印结束，胶从掩模变成污染物。灰化与湿法剥离要拿得干净，又不能伤已刻的衬底和硬掩模。</p><footer>—— 对照 resist strip / O₂ ash 在图形化后的公开步骤</footer></div><p><a href="/litho/barc-open-etch">上一课</a>仍把胶当掩模。本课是轨道补层最后一课：图形已经在下层，去掉胶和残碳。缺口不是再写显影，而是剥离选择比与残留。后课曝光机子系统从准分子激光另起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>干法灰化快，但对注入、金属、低 k 可能伤。湿法（溶剂、胺、酸）对硬化、离子注入胶可能去不净。植入后胶「皮」交联，要先灰化再湿法。把残留当「缺陷检测漏检」，会漏掉剥离窗口。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>常见：O₂ 灰化去大部分有机，湿法清灰与金属杂质，再漂洗。含硅 SOG 不能靠 O₂ 当有机胶去。金属氧化物胶要专用剥离，勿套 CAR 灰化。终点：表面亲水、XPS/缺陷可接受、衬底损失在预算内。</p>',7)),(e(),n(p,null,{default:r(()=>[d(i,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20MASK%5B%22%E8%83%B6%E4%BB%8D%E5%BD%93%E6%8E%A9%E6%A8%A1%22%5D%20--%3E%20XFER%5B%22%E8%BD%AC%E5%8D%B0%E5%AE%8C%E6%88%90%22%5D%0A%20%20XFER%20--%3E%20ASH%5B%22%E7%81%B0%E5%8C%96%22%5D%0A%20%20ASH%20--%3E%20WET%5B%22%E6%B9%BF%E6%B3%95%E5%89%A5%E7%A6%BB%22%5D%0A%20%20WET%20--%3E%20CLEAN%5B%22%E5%8F%AF%E8%BF%9B%E4%B8%8B%E5%B1%82%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">灰化会氧化衬底表面，金属线可能需要后续还原或清洗。剥离配方与「下一层是什么」绑定。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>氧化等离子体把碳氢变成挥发物。交联与植入损伤降低反应速率，留下壳。湿法从壳下钻蚀。选择比来自衬底是否也被氧化或腐蚀。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课结束涂胶显影轨道。不写主刻蚀化学（集成课）。扫描仪光源、物镜、工件台是下一课程。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>剥离是转印后的清洁合同，选择比针对已形成的衬底。</li><li>植入胶、金属胶、含硅层不能共用一条灰化。</li><li>出处：resist strip / ash 通识；接续开口课。</li></ul>',7))])}const S=s(E,[["render",_]]);export{T as __pageData,S as default};
